/**
 * Pronunciation for the narration: what is DISPLAYED (the correct written terms) is kept apart from
 * what is SPOKEN (the wording sent to the voice).
 *
 * Provider reality: the voice is generated by the video model (Seedance) from text inside its prompt.
 * There is no SSML, no phoneme markup and no pronunciation dictionary. The only lever is the wording
 * of the spoken text ("roh-ass", "G A four", "over twelve million dollars"), so this module never
 * produces markup. Whether the model then says it right is checked from the audio, not assumed.
 *
 * No per-acronym or per-company table lives here. How a term is said comes from, in order: operator
 * overrides, brand guidance, a language model that sees the campaign context, and finally generic
 * language rules (number words, currency symbols, a pronounceability heuristic). Pure apart from the
 * default decider, which calls the configured model and never throws.
 */
import { z } from "zod";
import type { Confidence, PronunciationDecision, PronunciationEntry, PronunciationKind, PronunciationLexicon, SpeechLine, SpeechSegment } from "@/lib/video/pipeline-types";

export const SEEDANCE_SPEECH_PROVIDER: PronunciationLexicon["provider"] = {
  ssml: false,
  phonemes: false,
  dictionary: false,
  note: "The voice is generated by the video model from text in the prompt. There is no SSML, phoneme markup or pronunciation dictionary, so the only control is the wording of the spoken text (respelling, spelled-out letters, numbers as words). A matching transcript does not prove the pronunciation was right.",
};

// ------------------------------------------------------------------ numbers as words

const SMALL = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"];
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
const SCALE_NAMES = ["", "thousand", "million", "billion", "trillion"];

function region(locale: string): string {
  return (locale.split(/[-_]/)[1] ?? "").toUpperCase();
}
/** British-style English says "one hundred and five". */
function usesAnd(locale: string): boolean {
  return ["AU", "GB", "NZ", "IE"].includes(region(locale));
}
/** Day before month (12/03 is 12 March). */
function dayFirst(locale: string): boolean {
  return ["AU", "GB", "NZ", "IE", "IN", "ZA"].includes(region(locale));
}

function below100(n: number): string {
  if (n < 20) return SMALL[n]!;
  const o = n % 10;
  return o ? `${TENS[Math.floor(n / 10)]}-${SMALL[o]}` : TENS[Math.floor(n / 10)]!;
}
function below1000(n: number, and: boolean): string {
  const h = Math.floor(n / 100);
  const r = n % 100;
  const parts: string[] = [];
  if (h) parts.push(`${SMALL[h]} hundred`);
  if (r) {
    if (h && and) parts.push("and");
    parts.push(below100(r));
  }
  return parts.join(" ");
}

function digitByDigit(digits: string): string {
  return digits.split("").map((d) => SMALL[Number(d)] ?? d).join(" ");
}

function integerWords(digits: string, and: boolean): string {
  const clean = digits.replace(/^0+(?=\d)/, "");
  if (clean === "0") return "zero";
  if (clean.length > 15) return digitByDigit(clean);
  const groups: number[] = [];
  for (let end = clean.length; end > 0; end -= 3) groups.push(Number(clean.slice(Math.max(0, end - 3), end)));
  const parts: string[] = [];
  for (let g = groups.length - 1; g >= 0; g -= 1) {
    const value = groups[g]!;
    if (!value) continue;
    const higher = groups.slice(g + 1).some(Boolean);
    const prefix = and && g === 0 && higher && value < 100 ? "and " : "";
    parts.push(`${prefix}${below1000(value, and)}${SCALE_NAMES[g] ? ` ${SCALE_NAMES[g]}` : ""}`);
  }
  return parts.join(" ");
}

/** A digit string such as "1200", "3.50" or "-7.25" (no thousands separators) as words. */
function digitStringToWords(raw: string, locale: string): string {
  const negative = raw.startsWith("-");
  const body = negative ? raw.slice(1) : raw;
  const [int = "0", frac] = body.split(".");
  const words = integerWords(int || "0", usesAnd(locale));
  const out = frac ? `${words} point ${digitByDigit(frac)}` : words;
  return negative ? `minus ${out}` : out;
}

/**
 * Integers to the trillions, negatives and decimals as words. British, Australian, New Zealand and
 * Irish English say "and" ("one hundred and five"); other locales do not ("one hundred five").
 */
export function numberToWords(n: number, opts?: { locale?: string }): string {
  if (!Number.isFinite(n)) return String(n);
  let text = String(n);
  if (/e/i.test(text)) text = n.toFixed(10).replace(/\.?0+$/, "");
  return digitStringToWords(text, opts?.locale ?? "en-US");
}

function ordinalFromCardinal(words: string): string {
  const m = words.match(/^(.*?)([a-z]+)$/);
  if (!m) return words;
  const last = m[2]!;
  const irregular: Record<string, string> = { one: "first", two: "second", three: "third", five: "fifth", eight: "eighth", nine: "ninth", twelve: "twelfth" };
  let ord = irregular[last];
  if (!ord) ord = last.endsWith("y") ? `${last.slice(0, -1)}ieth` : `${last}th`;
  return `${m[1]}${ord}`;
}
function ordinalWords(n: number, locale: string): string {
  return ordinalFromCardinal(integerWords(String(n), usesAnd(locale)));
}

/** 2026 is "twenty twenty-six", 1905 "nineteen oh five", 2005 "two thousand and five". */
function yearWords(year: number, locale: string): string {
  if (year >= 2000 && year <= 2009) return year === 2000 ? "two thousand" : `two thousand${usesAnd(locale) ? " and" : ""} ${SMALL[year - 2000]}`;
  const a = Math.floor(year / 100);
  const b = year % 100;
  const head = below100(a);
  if (b === 0) return `${head} hundred`;
  if (b < 10) return `${head} oh ${SMALL[b]}`;
  return `${head} ${below100(b)}`;
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
function monthName(token: string): string | null {
  const key = token.slice(0, 3).toLowerCase();
  return MONTHS.find((m) => m.slice(0, 3).toLowerCase() === key) ?? null;
}

// ------------------------------------------------------------------ detecting terms in display text

export type DetectedTerm = { term: string; kind: PronunciationKind; index: number };

const NUM = String.raw`(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?`;
const MAGNITUDE_WORD = String.raw`(?:\s?(?:thousand|million|billion|trillion)\b)`;
const MONTH_RE = String.raw`(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|June?|July?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)`;
const DAY_RE = String.raw`\d{1,2}(?:st|nd|rd|th)?(?!\d)`;
const YEAR_RE = String.raw`(?:1[5-9]|20)\d\d`;
const CURRENCY_PREFIX = String.raw`(?:US|AU|NZ|CA|HK|SG|A|C|S)\$|[$€£¥₹]`;
const TRAIL = String.raw`(?:\+|-(?![\w$€£]))?`;

type Pattern = { re: RegExp; kind: PronunciationKind };

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function brandPattern(name: string): RegExp | null {
  const tokens = name
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean);
  if (!tokens.length) return null;
  return new RegExp(`(?<![A-Za-z0-9])${tokens.map(escapeRe).join(String.raw`[\s\-]*`)}(?![A-Za-z0-9])`, "gi");
}

function staticPatterns(): Pattern[] {
  const list: Array<[string, PronunciationKind]> = [
    // currency with symbol, optional magnitude suffix and trailing +/-
    [String.raw`(?<![A-Za-z0-9$€£])(?:${CURRENCY_PREFIX})\s?${NUM}(?:${MAGNITUDE_WORD}|(?:[kK]|[mM]n?|[bB]n?)(?![A-Za-z0-9]))?${TRAIL}`, "currency"],
    [String.raw`(?<![\d.,$€£])${NUM}%\+?`, "percent"],
    [String.raw`(?<![\w.,$€£])${NUM}[xX×](?![A-Za-z0-9])`, "number"],
    [String.raw`(?<![\w:])\d{1,2}(?::\d{2})?\s?(?:[AaPp][Mm]|[AaPp]\.[Mm]\.)(?![A-Za-z0-9])`, "number"],
    [String.raw`(?<![\w])${DAY_RE}\s(?:of\s)?${MONTH_RE}(?![A-Za-z])(?:,?\s${YEAR_RE}(?!\d))?`, "date"],
    [String.raw`(?<![\w])${MONTH_RE}\s${DAY_RE}(?:,?\s${YEAR_RE}(?!\d))?`, "date"],
    [String.raw`(?<![\w])${MONTH_RE},?\s${YEAR_RE}(?!\d)`, "date"],
    [String.raw`(?<![\w/.])\d{1,2}/\d{1,2}(?:/\d{2,4})?(?![\d/])`, "date"],
    [String.raw`(?<![A-Za-z0-9.])(?:[A-Za-z]\.){2,}`, "abbreviation"],
    [String.raw`(?<![A-Za-z])(?:vs|etc|approx|Mr|Mrs|Ms|Dr)\.`, "abbreviation"],
    [String.raw`(?<![\w.,])\d+(?:st|nd|rd|th)(?![A-Za-z0-9])`, "number"],
    [String.raw`(?<![\w.,$€£])${NUM}(?:${MAGNITUDE_WORD}|(?:[kK]|[MB]n?|bn)(?![A-Za-z0-9]))?${TRAIL}(?![A-Za-z\d])`, "number"],
    [String.raw`(?<![A-Za-z0-9])(?=[A-Z0-9]*[A-Z])(?=[A-Z0-9]*\d)[A-Z0-9]{2,}(?![A-Za-z0-9])`, "acronym"],
    [String.raw`(?<![A-Za-z0-9])[A-Z]&[A-Z](?:&[A-Z])*(?![A-Za-z0-9])`, "abbreviation"],
    [String.raw`(?<![A-Za-z0-9])[A-Z]{2,}s?(?![A-Za-z0-9])`, "acronym"],
    [String.raw`(?<![A-Za-z0-9])(?:[a-z]+[A-Z][A-Za-z]*|[A-Z][a-z]+[A-Z][A-Za-z]*)(?![A-Za-z0-9])`, "technical"],
    [String.raw`&`, "technical"],
    [String.raw`(?<=\s)\+(?=\s)|(?<=[A-Za-z])\+(?=[A-Za-z])`, "technical"],
  ];
  return list.map(([source, kind]) => ({ re: new RegExp(source, "g"), kind }));
}

const YEAR_CUES = new Set(["in", "since", "by", "from", "until", "till", "during", "of", "year", "fy", "before", "after", "through", "to", "circa", "around", "early", "late", "mid"]);

/** Whether a bare four-digit number reads as a year: after a cue word, after a month, or ending a clause. */
function readsAsYear(text: string, index: number, length: number): boolean {
  const before = text.slice(0, index).trimEnd();
  const prev = (before.match(/([A-Za-z]+)$/)?.[1] ?? "").toLowerCase();
  if (YEAR_CUES.has(prev) || /^(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)$/.test(prev)) return true;
  const after = text.slice(index + length).trimStart();
  return after === "" || /^[.,;:!?)]/.test(after);
}

/**
 * Find the terms in the DISPLAY text whose pronunciation needs a decision: the brand name (and its
 * spaced or cased variants), all-caps tokens and letter+digit mixes, currency, percentages, multiples,
 * numbers, dates and years, ordinals, "24/7", dotted abbreviations, mixed-case technical terms and
 * symbols read aloud. Each term is the exact substring; matches never overlap and the longest wins.
 */
export function detectTerms(text: string, ctx?: { brandName?: string | null }): DetectedTerm[] {
  const patterns: Pattern[] = [];
  const brand = ctx?.brandName?.trim() ? brandPattern(ctx.brandName.trim()) : null;
  if (brand) patterns.push({ re: brand, kind: "brand" });
  patterns.push(...staticPatterns());
  const candidates: Array<{ term: string; kind: PronunciationKind; index: number; prio: number }> = [];
  patterns.forEach((p, prio) => {
    for (const m of text.matchAll(p.re)) {
      if (!m[0]) continue;
      let kind = p.kind;
      if (kind === "number" && /^\d{4}$/.test(m[0]) && /^(?:1[5-9]|20)\d\d$/.test(m[0]) && readsAsYear(text, m.index!, m[0].length)) kind = "date";
      candidates.push({ term: m[0], kind, index: m.index!, prio });
    }
  });
  candidates.sort((a, b) => b.term.length - a.term.length || a.prio - b.prio || a.index - b.index);
  const taken = new Array<boolean>(text.length).fill(false);
  const out: DetectedTerm[] = [];
  for (const c of candidates) {
    let free = true;
    for (let i = c.index; i < c.index + c.term.length; i += 1) if (taken[i]) free = false;
    if (!free) continue;
    for (let i = c.index; i < c.index + c.term.length; i += 1) taken[i] = true;
    out.push({ term: c.term, kind: c.kind, index: c.index });
  }
  return out.sort((a, b) => a.index - b.index);
}

// ------------------------------------------------------------------ rule decisions

const CURRENCIES: Record<string, { adjective?: string; code?: string; major: [string, string]; minor?: [string, string] }> = {
  $: { major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "A$": { adjective: "Australian", code: "AUD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "AU$": { adjective: "Australian", code: "AUD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "US$": { adjective: "U S", code: "USD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "NZ$": { adjective: "New Zealand", code: "NZD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "CA$": { adjective: "Canadian", code: "CAD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "C$": { adjective: "Canadian", code: "CAD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "HK$": { adjective: "Hong Kong", code: "HKD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "SG$": { adjective: "Singapore", code: "SGD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "S$": { adjective: "Singapore", code: "SGD", major: ["dollar", "dollars"], minor: ["cent", "cents"] },
  "€": { major: ["euro", "euros"], minor: ["cent", "cents"] },
  "£": { major: ["pound", "pounds"], minor: ["penny", "pence"] },
  "¥": { major: ["yen", "yen"] },
  "₹": { major: ["rupee", "rupees"] },
};
const REGION_CURRENCY: Record<string, string> = { AU: "AUD", NZ: "NZD", CA: "CAD", US: "USD", SG: "SGD", HK: "HKD" };
const CODE_ADJECTIVE: Record<string, string> = { AUD: "Australian", USD: "U S", NZD: "New Zealand", CAD: "Canadian", SGD: "Singapore", HKD: "Hong Kong" };

function magnitudeWord(raw: string): string {
  const k = raw.trim().toLowerCase();
  if (k === "k" || k === "thousand") return "thousand";
  if (k.startsWith("m")) return "million";
  if (k.startsWith("b")) return "billion";
  if (k === "trillion") return "trillion";
  return k;
}

const VOWELS = "AEIOU";
const CONSONANTS_ONSET2 = /^(?:[BCDFGKPT][LR]|S[CKLMNPTW]|SH|CH|TH|PH|WH|WR|KN|GN|QU|[DT]W)$/;
const CONSONANTS_ONSET3 = /^(?:STR|SCR|SPR|SPL|SHR|THR|SQU|CHR|SCH)$/;
const CODA2 = /^(?:[LNR][DKTPSFMCV]|S[TPK]|[MN][PTDK]|[FPKX]T|CH|SH|TH|NG|NK|CK|SS|LL|FF|ZZ|RM|LM|RN|NS|TS|DS|KS|PS|LS|RS|MS|GS|BS)$/;
/** Two-letter word endings that real words have; "EO" (SEO, CEO) and "OI" (ROI) are not among them. */
const FINAL_VOWEL_PAIRS = new Set(["EE", "OO", "OE", "IE", "AY", "EY", "OY", "UE", "EA", "OW", "AW", "EW", "OU", "AU", "IA", "IO"]);

function isVowelAt(s: string, i: number): boolean {
  const ch = s[i]!;
  return VOWELS.includes(ch) || (ch === "Y" && i > 0 && !VOWELS.includes(s[i - 1]!));
}

type Run = { vowel: boolean; text: string };
function runsOf(s: string): Run[] {
  const runs: Run[] = [];
  for (let i = 0; i < s.length; i += 1) {
    const v = isVowelAt(s, i);
    const last = runs[runs.length - 1];
    if (last && last.vowel === v) last.text += s[i];
    else runs.push({ vowel: v, text: s[i]! });
  }
  return runs;
}

/** Whether letters could be said as an ordinary word: sane consonant clusters, no stray Q, a word-like ending. */
function pronounceable(s: string): { ok: boolean; syllables: number; alternating: boolean } {
  const runs = runsOf(s);
  const syllables = runs.filter((r) => r.vowel).length;
  if (!syllables || /Q(?!U)/.test(s)) return { ok: false, syllables, alternating: false };
  let ok = true;
  let alternating = true;
  runs.forEach((r, idx) => {
    const first = idx === 0;
    const last = idx === runs.length - 1;
    if (r.vowel) {
      if (r.text.length > 2) ok = false;
      if (r.text.length > 1) alternating = false;
      if (last && r.text.length === 2 && !FINAL_VOWEL_PAIRS.has(r.text)) ok = false;
    } else {
      if (r.text.length > 1) alternating = false;
      if (first) {
        if (r.text.length === 2 && !CONSONANTS_ONSET2.test(r.text)) ok = false;
        if (r.text.length === 3 && !CONSONANTS_ONSET3.test(r.text)) ok = false;
        if (r.text.length > 3) ok = false;
      } else if (last) {
        if (r.text.length === 2 && !CODA2.test(r.text)) ok = false;
        if (r.text.length > 2) ok = false;
      } else if (r.text.length > 3) ok = false;
    }
  });
  return { ok, syllables, alternating };
}

const spellLetters = (letters: string) => letters.toUpperCase().split("").join(" ");

type Verdict = { decision: PronunciationDecision; spoken: string; reason: string; confidence: Confidence; needsReview: boolean };

/**
 * The hard case: an all-caps token. Heuristic, documented:
 *  - no vowels (CRM, SMS, HTML): can only be spelled, high confidence;
 *  - vowels but not word-shaped (clusters like KP/CP/CT, a Q without U, endings like EO or OI as in
 *    SEO and ROI): an initialism, spelled, high confidence for up to five letters;
 *  - word-shaped and five or more letters with two or more syllables (SHOPIFY, UNICEF): said as a word;
 *  - word-shaped but short (ROAS, NASA, USP, UK): genuinely ambiguous. Spelled (the safer reading, never
 *    a made-up expansion), low confidence, flagged for review.
 */
function acronymVerdict(token: string): Verdict {
  const plural = /[A-Z]s$/.test(token);
  const letters = plural ? token.slice(0, -1) : token;
  const tail = plural ? "s" : "";
  const spelled = `${spellLetters(letters)}${tail}`;
  const n = letters.length;
  const { ok, syllables } = pronounceable(letters);
  if (syllables === 0) return { decision: "spell", spoken: spelled, reason: "No vowels, so it can only be read letter by letter.", confidence: "high", needsReview: false };
  if (!ok) {
    return {
      decision: "spell",
      spoken: spelled,
      reason: "Not shaped like a word (consonant cluster or word ending no word has), so it reads as an initialism.",
      confidence: n <= 5 ? "high" : "medium",
      needsReview: false,
    };
  }
  if (n >= 5 && syllables >= 2) {
    return { decision: "word", spoken: `${letters.toLowerCase()}${tail}`, reason: "Long and word-shaped with several syllables, so it is said as a word.", confidence: n >= 6 ? "high" : "medium", needsReview: false };
  }
  return {
    decision: "spell",
    spoken: spelled,
    reason: `Short and could be said as the word "${letters.toLowerCase()}" or spelled letter by letter. Spelled as the safer reading. Give guidance or an override to say it as a word or as its full name.`,
    confidence: "low",
    needsReview: true,
  };
}

/** A letter+digit mix such as GA4 or B2B: letters spelled, digits said as words ("G A four"). */
function alphanumericVerdict(token: string): Verdict {
  const parts = token.match(/[A-Z]+|\d+/g) ?? [token];
  let longDigits = false;
  const spoken = parts
    .map((p) => {
      if (/^\d+$/.test(p)) {
        if (p.length <= 2) return digitStringToWords(p, "en-US");
        longDigits = true;
        return digitByDigit(p);
      }
      return spellLetters(p);
    })
    .join(" ");
  return { decision: "spell", spoken, reason: "Letters and digits mixed: letters spelled, digits said as words.", confidence: longDigits ? "medium" : "high", needsReview: longDigits };
}

function currencyAdjective(prefix: string, ctx: { locale: string; currency?: string | null }): string | undefined {
  const info = CURRENCIES[prefix];
  if (!info) return undefined;
  if (prefix !== "$") return info.adjective;
  const wanted = ctx.currency?.trim().toUpperCase();
  const home = REGION_CURRENCY[region(ctx.locale)];
  if (wanted && home && wanted !== home && CODE_ADJECTIVE[wanted]) return CODE_ADJECTIVE[wanted];
  return undefined;
}

function plainName(name: string): boolean {
  return name.split(/\s+/).every((w) => /^[A-Z][a-z]+$/.test(w) && /[aeiouy]/i.test(w));
}
const squash = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

/**
 * The deterministic fallback, source "rule". Numbers, currency, percentages, multiples, times and
 * dates become words with the right context (the symbol and the locale decide "dollars", "and",
 * day-before-month). All-caps tokens use the pronounceability heuristic above; ambiguous ones are
 * flagged and never expanded to a phrase this code cannot know.
 */
export function ruleDecision(term: DetectedTerm, ctx: { locale: string; brandName?: string | null; currency?: string | null }): PronunciationEntry {
  const t = term.term;
  const locale = ctx.locale || "en-US";
  const make = (kind: PronunciationKind, v: Verdict): PronunciationEntry => ({ term: t, kind, ...v, source: "rule" });
  const expand = (kind: PronunciationKind, spoken: string, reason: string, confidence: Confidence = "high", needsReview = false) =>
    make(kind, { decision: "expand", spoken, reason, confidence, needsReview });
  const num = (s: string) => digitStringToWords(s.replace(/,/g, ""), locale);

  // brand
  if (term.kind === "brand" || (ctx.brandName && squash(t) === squash(ctx.brandName))) {
    const canonical = ctx.brandName?.trim() || t;
    if (/^[A-Z]{2,}$/.test(canonical)) return make("brand", acronymVerdict(canonical));
    const plain = plainName(canonical);
    return make("brand", {
      decision: "verbatim",
      spoken: canonical,
      reason: plain ? "Brand name said as written, in its canonical spelling." : "Brand name with an unusual spelling: said as written, but how the voice reads it is a guess.",
      confidence: plain ? "medium" : "low",
      needsReview: !plain,
    });
  }

  // currency
  let m = t.match(new RegExp(`^(${CURRENCY_PREFIX})\\s?(${NUM})(?:\\s?(thousand|million|billion|trillion)|([kK]|[mM]n?|[bB]n?))?(\\+|-)?$`));
  if (m) {
    const [, prefix = "$", amount = "0", wordMag, symMag, sign] = m;
    const info = CURRENCIES[prefix]!;
    const mag = wordMag ?? symMag;
    const adjective = currencyAdjective(prefix, ctx);
    const clean = amount.replace(/,/g, "");
    const isOne = !mag && /^1(?:\.0+)?$/.test(clean);
    const unit = `${adjective ? `${adjective} ` : ""}${isOne ? info.major[0] : info.major[1]}`;
    const [whole = "0", frac] = clean.split(".");
    let body: string;
    if (!mag && frac && frac.length === 2 && info.minor) {
      body = Number(frac) === 0 ? `${num(whole)} ${unit}` : `${num(whole)} ${unit} and ${num(String(Number(frac)))} ${Number(frac) === 1 ? info.minor[0] : info.minor[1]}`;
    } else {
      body = `${num(clean)}${mag ? ` ${magnitudeWord(mag)}` : ""} ${unit}`;
    }
    const spoken = `${sign === "+" ? "over " : ""}${body}`;
    return sign === "-"
      ? expand("currency", spoken, "Amount with a trailing minus sign: the sign is not said because its meaning is unknown.", "low", true)
      : expand("currency", spoken, `Currency amount expanded to words (${info.adjective ?? "dollars"}${sign === "+" ? ", trailing + read as \"over\"" : ""}).`);
  }

  // percent
  m = t.match(new RegExp(`^(${NUM})%(\\+)?$`));
  if (m) return expand("percent", `${m[2] ? "over " : ""}${num(m[1]!)} percent`, "Percentage expanded to words.");

  // multiple
  m = t.match(new RegExp(`^(${NUM})[xX×]$`));
  if (m) return expand("number", `${num(m[1]!)} ${/^1(?:\.0+)?$/.test(m[1]!) ? "time" : "times"}`, "Multiple read as \"times\".");

  // clock time
  m = t.match(/^(\d{1,2})(?::(\d{2}))?\s?([AaPp])\.?[Mm]\.?$/);
  if (m) {
    const minutes = m[2] ? Number(m[2]) : 0;
    const mm = minutes === 0 ? "" : minutes < 10 ? ` oh ${SMALL[minutes]}` : ` ${below100(minutes)}`;
    return expand("number", `${num(m[1]!)}${mm} ${m[3]!.toUpperCase()} M`, "Clock time said in words with the A M or P M spelled.");
  }

  // 24/7
  if (t === "24/7") return expand("number", "twenty-four seven", "The idiom 24/7 said as \"twenty-four seven\".");

  // dates in words
  const monthRe = new RegExp(`^(?:(${DAY_RE})\\s(?:of\\s)?(${MONTH_RE})|(${MONTH_RE})\\s(${DAY_RE}))(?:,?\\s(${YEAR_RE}))?$`);
  m = t.match(monthRe);
  if (m) {
    const day = Number((m[1] ?? m[4])!.replace(/\D/g, ""));
    const month = monthName((m[2] ?? m[3])!)!;
    const year = m[5] ? ` ${yearWords(Number(m[5]), locale)}` : "";
    const spoken = dayFirst(locale) ? `the ${ordinalWords(day, locale)} of ${month}${year}` : `${month} ${ordinalWords(day, locale)}${year}`;
    return expand("date", spoken, "Date said in words in the locale's order.");
  }
  m = t.match(new RegExp(`^(${MONTH_RE}),?\\s(${YEAR_RE})$`));
  if (m) return expand("date", `${monthName(m[1]!)} ${yearWords(Number(m[2]), locale)}`, "Month and year said in words.");
  m = t.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    let day = dayFirst(locale) ? a : b;
    let month = dayFirst(locale) ? b : a;
    if (month > 12 && day <= 12) [day, month] = [month, day];
    if (month < 1 || month > 12 || day < 1 || day > 31) return make("date", { decision: "verbatim", spoken: t, reason: "Looks like a date but is not a valid one; left as written.", confidence: "low", needsReview: true });
    const ambiguous = a <= 12 && b <= 12 && a !== b;
    const yr = m[3] ? ` ${yearWords(m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]), locale)}` : "";
    const name = MONTHS[month - 1]!;
    const spoken = dayFirst(locale) ? `the ${ordinalWords(day, locale)} of ${name}${yr}` : `${name} ${ordinalWords(day, locale)}${yr}`;
    return expand("date", spoken, ambiguous ? `Day/month order is ambiguous; read as ${dayFirst(locale) ? "day/month" : "month/day"} for ${locale}.` : "Numeric date said in words.", ambiguous ? "low" : "high", ambiguous);
  }

  // ordinal
  m = t.match(/^(\d+)(?:st|nd|rd|th)$/);
  if (m) return expand("number", ordinalWords(Number(m[1]), locale), "Ordinal said in words.");

  // plain number, with optional magnitude and trailing sign
  m = t.match(new RegExp(`^(${NUM})(?:\\s?(thousand|million|billion|trillion)|([kK]|[MB]n?|bn))?(\\+|-)?$`));
  if (m) {
    const [, amount = "0", wordMag, symMag, sign] = m;
    const mag = wordMag ?? symMag;
    const bareYear = !mag && !sign && /^(?:1[5-9]|20)\d\d$/.test(amount);
    if (bareYear && term.kind === "date") return expand("date", yearWords(Number(amount), locale), "Year said the way years are said.");
    const body = `${num(amount)}${mag ? ` ${magnitudeWord(mag)}` : ""}`;
    if (sign === "-") return expand("number", body, "Number with a trailing minus sign: the sign is not said because its meaning is unknown.", "low", true);
    if (bareYear) return expand("number", body, "Four digits that could be a year or a quantity; read as a quantity.", "low", true);
    return expand("number", `${sign === "+" ? "over " : ""}${body}`, "Number expanded to words.", mag && !/\d\s/.test(t) && /^[kK]/.test(mag) ? "medium" : "high");
  }

  // abbreviations with periods
  const table: Record<string, string> = { "e.g.": "for example", "i.e.": "that is", "vs.": "versus", "etc.": "et cetera", "approx.": "approximately", "mr.": "mister", "mrs.": "missus", "ms.": "miss", "dr.": "doctor", "a.m.": "A M", "p.m.": "P M" };
  const known = table[t.toLowerCase()];
  if (known) return make("abbreviation", { decision: "expand", spoken: known, reason: "Common written abbreviation said in full.", confidence: "high", needsReview: false });
  if (/^(?:[A-Za-z]\.){2,}$/.test(t)) return make("abbreviation", { decision: "spell", spoken: spellLetters(t.replace(/\./g, "")), reason: "Dotted initials spelled letter by letter.", confidence: "medium", needsReview: false });

  // R&D, Q&A
  if (/^[A-Z](?:&[A-Z])+$/.test(t)) return make("abbreviation", { decision: "spell", spoken: t.split("&").join(" and "), reason: "Letters joined by an ampersand, said as letters with \"and\".", confidence: "high", needsReview: false });

  // letters + digits, all caps
  if (/^[A-Z0-9]{2,}$/.test(t) && /[A-Z]/.test(t) && /\d/.test(t)) return make(term.kind === "acronym" ? "acronym" : term.kind, alphanumericVerdict(t));

  // all caps
  if (/^[A-Z]{2,}s?$/.test(t)) return make("acronym", acronymVerdict(t));

  // mixed case technical term
  if (/^(?:[a-z]+[A-Z][A-Za-z]*|[A-Z][a-z]+[A-Z][A-Za-z]*)$/.test(t)) {
    const short = t.length <= 4;
    return make("technical", { decision: "verbatim", spoken: t, reason: short ? "Short mixed-case term: said as written, but the voice may read it differently." : "Mixed-case term said as written.", confidence: short ? "low" : "medium", needsReview: short });
  }

  // symbols
  if (t === "&") return make("technical", { decision: "expand", spoken: "and", reason: "Ampersand said as \"and\".", confidence: "high", needsReview: false });
  if (t === "+") return make("technical", { decision: "expand", spoken: "plus", reason: "Plus sign said as \"plus\".", confidence: "high", needsReview: false });

  return make(term.kind, { decision: "verbatim", spoken: t, reason: "No rule applies; left as written.", confidence: "low", needsReview: true });
}

// ------------------------------------------------------------------ building the lexicon

export type LexiconDecider = (input: {
  terms: Array<{ term: string; kind: PronunciationKind; examples: string[] }>;
  locale: string;
  brandName: string | null;
  guidance: string[];
  campaign: string;
}) => Promise<Array<{ term: string; decision: PronunciationDecision; spoken: string; reason: string; confidence: Confidence }>>;

const DECISIONS = ["spell", "word", "expand", "verbatim"] as const;
const deciderSchema = z.object({
  decisions: z.array(
    z.object({
      term: z.string().describe("The term exactly as given, same spelling and case"),
      decision: z.enum(DECISIONS),
      spoken: z.string().describe("The words to put in the voice script for this term. For verbatim, repeat the term."),
      reason: z.string().describe("One sentence of reasoning that uses the campaign context"),
      confidence: z.enum(["high", "medium", "low"]),
    }),
  ),
});

/**
 * Asks the configured model how each term should be said, given the campaign. Returns [] when no model
 * is configured. May throw on a model error: buildLexicon catches that and uses the rules.
 */
export const defaultDecider: LexiconDecider = async (input) => {
  const { modelCandidates, withModelFallback } = await import("@/lib/video/model-fallback");
  const candidates = modelCandidates();
  if (!candidates.length) return [];
  const { generateObject } = await import("ai");
  const system =
    "You decide how a text-to-speech voice should say terms from an ad script. The voice reads plain text only: there is no SSML, no phoneme markup and no dictionary, so the only lever is the wording you give it.";
  const prompt = [
    `Campaign context: ${input.campaign || "(none given)"}`,
    `Language and accent: ${input.locale}`,
    input.brandName ? `Brand name: ${input.brandName}` : "",
    input.guidance.length ? `Brand guidance:\n${input.guidance.map((g) => `- ${g}`).join("\n")}` : "",
    "",
    "For each term, decide how it is said:",
    '- "spell": letter by letter, written as spaced capitals ("S E O"); digits as words ("G A four").',
    '- "word": said as an ordinary word, written as a plain respelling the voice will read correctly (for example a hyphenated respelling).',
    '- "expand": replaced by other words (numbers and currency in words, an abbreviation in full). Only expand an abbreviation to its full name when the context makes the meaning certain.',
    '- "verbatim": left exactly as written. Allowed whenever the voice will already say it correctly.',
    "Rules: the DISPLAY text is never changed, only what is spoken. No markup of any kind. Use the locale's conventions (currency names, 'and' in numbers, date order). Use the campaign context to decide, for example whether an all-caps term is a word or an initialism. If you are guessing, say so with low confidence.",
    "",
    "Terms:",
    ...input.terms.map((t) => `- ${JSON.stringify(t.term)} (${t.kind}) in: ${t.examples.map((e) => JSON.stringify(e)).join(" | ")}`),
  ]
    .join("\n");
  const { decisions } = await withModelFallback(async (model) => (await generateObject({ model, schema: deciderSchema, temperature: 0, system, prompt })).object, candidates);
  return decisions;
};

const MARKUP = /[<>{}[\]]/;
/** Remove anything that could be read as markup from text bound for the voice. */
function plainSpeech(s: string): string {
  return s.replace(/[<>{}[\]]/g, "").replace(/\s+/g, " ").trim();
}

function guessDecision(term: string, spoken: string): PronunciationDecision {
  if (spoken === term) return "verbatim";
  if (/^(?:[A-Za-z0-9]\s)+[A-Za-z0-9]$/.test(spoken)) return "spell";
  return /\s/.test(spoken) ? "expand" : "word";
}

function literalPattern(key: string): RegExp {
  const start = /^[A-Za-z0-9]/.test(key) ? "(?<![A-Za-z0-9])" : "";
  const end = /[A-Za-z0-9]$/.test(key) ? "(?![A-Za-z0-9])" : "";
  return new RegExp(`${start}${escapeRe(key)}${end}`);
}

export async function buildLexicon(input: {
  lines: Array<{ sceneNumber: number; text: string }>;
  brandName: string | null;
  locale: string;
  overrides?: Record<string, string>;
  brandGuidance?: Array<{ term: string; spoken: string }>;
  campaign?: string;
  provider?: PronunciationLexicon["provider"];
  decide?: LexiconDecider;
  now?: string;
}): Promise<PronunciationLexicon> {
  const locale = input.locale || "en-US";
  const overrides = input.overrides ?? {};
  const guidance = input.brandGuidance ?? [];
  const found = new Map<string, { kind: PronunciationKind; examples: string[] }>();
  const note = (term: string, kind: PronunciationKind, line: string) => {
    const rec = found.get(term) ?? { kind, examples: [] };
    if (rec.examples.length < 2 && !rec.examples.includes(line)) rec.examples.push(line);
    found.set(term, rec);
  };
  for (const line of input.lines) {
    for (const d of detectTerms(line.text, { brandName: input.brandName })) note(d.term, d.kind, line.text);
    for (const key of [...Object.keys(overrides), ...guidance.map((g) => g.term)]) {
      if (key.trim() && literalPattern(key).test(line.text)) note(key, "technical", line.text);
    }
  }

  const lookup = <T,>(items: Array<[string, T]>, term: string): T | undefined => {
    const exact = items.find(([k]) => k === term);
    if (exact) return exact[1];
    return items.find(([k]) => k.toLowerCase() === term.toLowerCase())?.[1];
  };
  const overrideItems = Object.entries(overrides).map(([k, v]) => [k, v] as [string, string]);
  const guidanceItems = guidance.map((g) => [g.term, g.spoken] as [string, string]);

  const entries = new Map<string, PronunciationEntry>();
  const open: Array<{ term: string; kind: PronunciationKind; examples: string[] }> = [];
  for (const [term, rec] of found) {
    const forced = lookup(overrideItems, term);
    if (forced !== undefined && forced.trim()) {
      entries.set(term, { term, kind: rec.kind, decision: guessDecision(term, forced.trim()), spoken: plainSpeech(forced), reason: "Set by the operator for this video.", confidence: "high", needsReview: false, source: "operator" });
      continue;
    }
    const guided = lookup(guidanceItems, term);
    if (guided !== undefined && guided.trim()) {
      entries.set(term, { term, kind: rec.kind, decision: guessDecision(term, guided.trim()), spoken: plainSpeech(guided), reason: "Taken from the brand's pronunciation guidance.", confidence: "high", needsReview: false, source: "brand_guidance" });
      continue;
    }
    open.push({ term, kind: rec.kind, examples: rec.examples });
  }

  // The model decides what is left; anything it skips, gets wrong or cannot answer falls back to the rules.
  let answers: Awaited<ReturnType<LexiconDecider>> = [];
  if (open.length) {
    try {
      answers = await (input.decide ?? defaultDecider)({
        terms: open,
        locale,
        brandName: input.brandName,
        guidance: guidance.map((g) => `${g.term}: say "${g.spoken}"`),
        campaign: input.campaign ?? "",
      });
    } catch {
      answers = [];
    }
  }
  const asked = new Map(open.map((o) => [o.term, o]));
  const accepted = new Map<string, PronunciationEntry>();
  for (const a of Array.isArray(answers) ? answers : []) {
    const rec = a && typeof a.term === "string" ? asked.get(a.term) : undefined;
    if (!rec || accepted.has(a.term)) continue;
    if (!DECISIONS.includes(a.decision)) continue;
    if (typeof a.spoken === "string" && MARKUP.test(a.spoken)) continue; // the model tried markup: the voice takes none
    const spoken = typeof a.spoken === "string" ? plainSpeech(a.spoken) : "";
    const verbatim = a.decision === "verbatim";
    if (!verbatim && !spoken) continue;
    const confidence: Confidence = a.confidence === "high" || a.confidence === "medium" || a.confidence === "low" ? a.confidence : "low";
    accepted.set(a.term, {
      term: a.term,
      kind: rec.kind,
      decision: a.decision,
      spoken: verbatim ? a.term : spoken,
      reason: String(a.reason ?? "").trim() || "Chosen by the model from the campaign context.",
      confidence,
      needsReview: confidence !== "high",
      source: "model",
    });
  }
  for (const [term, rec] of found) {
    if (entries.has(term)) continue;
    entries.set(term, accepted.get(term) ?? ruleDecision({ term, kind: rec.kind, index: 0 }, { locale, brandName: input.brandName }));
  }

  return {
    locale,
    entries: [...found.keys()].map((t) => entries.get(t)!),
    provider: input.provider ?? SEEDANCE_SPEECH_PROVIDER,
    createdAt: input.now ?? new Date().toISOString(),
  };
}

// ------------------------------------------------------------------ applying it to a line

const isWordChar = (c: string | undefined) => c !== undefined && /[A-Za-z0-9]/.test(c);

/**
 * Turn a display line into what is spoken. The segments reproduce the display string exactly
 * (whitespace and punctuation included); only the terms in the lexicon are replaced in `spoken`.
 * Longest term first, case-sensitive, never inside a longer word. Never emits markup.
 */
export function applyLexicon(sceneNumber: number, display: string, lexicon: PronunciationLexicon): SpeechLine {
  const entries = [...lexicon.entries].filter((e) => e.term).sort((a, b) => b.term.length - a.term.length);
  const segments: SpeechSegment[] = [];
  let plain = "";
  const flush = () => {
    if (plain) segments.push({ display: plain, spoken: plain.replace(/[<>{}[\]]/g, "") });
    plain = "";
  };
  let i = 0;
  while (i < display.length) {
    let hit: PronunciationEntry | undefined;
    for (const e of entries) {
      if (!display.startsWith(e.term, i)) continue;
      if (isWordChar(e.term[0]) && isWordChar(display[i - 1])) continue;
      if (isWordChar(e.term[e.term.length - 1]) && isWordChar(display[i + e.term.length])) continue;
      hit = e;
      break;
    }
    if (!hit) {
      plain += display[i];
      i += 1;
      continue;
    }
    flush();
    const end = i + hit.term.length;
    let spoken = plainSpeech(hit.spoken) || hit.term;
    // An abbreviation that ends the line keeps its full stop so the sentence still lands.
    if (hit.term.endsWith(".") && !spoken.endsWith(".") && display.slice(end).trim() === "") spoken += ".";
    segments.push({ display: hit.term, spoken, term: hit.term });
    i = end;
  }
  flush();
  const uncertain: string[] = [];
  for (const s of segments) {
    if (!s.term) continue;
    const entry = lexicon.entries.find((e) => e.term === s.term);
    if (entry?.needsReview && !uncertain.includes(s.term)) uncertain.push(s.term);
  }
  return { sceneNumber, display, spoken: segments.map((s) => s.spoken).join(""), segments, uncertain };
}

export function lexiconNeedsReview(lexicon: PronunciationLexicon): PronunciationEntry[] {
  return lexicon.entries.filter((e) => e.needsReview);
}
